mapper.select:
SELECT p.id, p.name, p.description, p.status, p.user_id, p.space_dir, p.agent_id, p.auto_iterate, p.iterate_prompt, p.session_id, p.create_time, p.update_time
FROM projects p
WHERE p.user_id = #{userId}

    AND (p.name LIKE CONCAT('%', #{keyword}, '%') OR p.description LIKE CONCAT('%', #{keyword}, '%'))


    AND p.status = #{status}

ORDER BY p.id DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*)
FROM projects
WHERE user_id = #{userId}

    AND (name LIKE CONCAT('%', #{keyword}, '%') OR description LIKE CONCAT('%', #{keyword}, '%'))


    AND status = #{status}
